      let response;
      try{response=id?await http.patch(`inventory/${resource}/${z.uuid().parse(id)}/`,body,{...options(language,tokens.access),params:{view:'receipt'}}):await http.post(`inventory/${resource}/`,body,{...options(language,tokens.access),params:{view:'receipt'}});}
      catch(error){if(!isAxiosError(error)||!error.response||error.response.status>=500)throw new InventorySaveUnconfirmed();throw error;}
