      const q=inventoryQuerySchema.parse(query);const path={items:'items',lots:'lotes',alerts:'alertas',suppliers:'fornecedores'}[q.kind];
      const params={page:q.page,page_size:20,...(q.kind==='items'?{view:'operational',search:q.search,...(q.category?{categoria:q.category}:{}),...(q.status!=='all'?{status:q.status}:{})}:q.kind==='lots'?{view:'operational',item:q.item}:q.kind==='suppliers'?{search:q.search}:{})};
      const data=(await http.get(`inventory/${path}/`,{...options(language,tokens.access),params,signal})).data;
      return q.kind==='items'?itemPageSchema.parse(data):q.kind==='lots'?(()=>{const result=lotPageSchema.parse(data);if(result.results.some(lot=>lot.item!==q.item))throw Error('invalid item scope');return result;})():q.kind==='alerts'?alertPageSchema.parse(data):supplierPageSchema.parse(data);
